var tokenMatch = src.match(/token\s*=\s*"([^"]+)"/);
var html = src;
if (tokenMatch) {
    var token = tokenMatch[1];
    var tourl = baseUrl + "?challenge=" + encodeURIComponent(token);
    html = java.ajax(tourl);
}
var section = html.match(/<section[^>]*>\s*([\s\S]*?)\s*<\/section>/i);
if (!section) {
    "";
} else {
    var text = section[1]
        .replace(/<br\s*\/?>/gi, "\n")
        .replace(/<\/p>\s*<p[^>]*>/gi, "\n")
        .replace(/<\/?p[^>]*>/gi, "")
        .trim();
    text;
}

