function urlCoverUrl(url) {
    const {java, cache, source} = this
    let isIPDirect
    if (source.bookSourceName.includes("备用")|| source.bookSourceName.includes("漫画")) {
        isIPDirect = JSON.parse(String(source.variableComment).match(RegExp(/{([\s\S]*?)}/gm)))?.IPDirect || false
    } else {
        isIPDirect = JSON.parse(cache.get("pixivSettings")).IPDirect || false
    }

    let headers = {"Referer": "https://www.pixiv.net/"}
    if (isIPDirect && url.trim()) {
        if (url.includes("i.pximg.net")) {
            url = url.replace("https://i.pximg.net", "https://210.140.139.133")
            headers.host = "i.pximg.net"
        } else {
            url = url.replace("https://s.pximg.net", "https://210.140.139.133")
            headers.host = "s.pximg.net"
        }
    }
    return `${url}, ${JSON.stringify({headers: headers})}`
}

function dateFormat(str) {
    let addZero = function (num) {
        return num < 10 ? '0' + num : num;
    }
    let time = new Date(str);
    let Y = time.getFullYear() + "年";
    let M = addZero(time.getMonth() + 1) + "月";
    let D = addZero(time.getDate()) + "日";
    return Y + M + D;
}
function timeFormat(str) {
    let addZero = function (num) {
        return num < 10 ? '0' + num : num;
    }
    let time = new Date(str);
    let YY = time.getFullYear()
    let MM = addZero(time.getMonth() + 1)
    let DD = addZero(time.getDate())
    let hh = addZero(time.getHours())
    let mm = addZero(time.getMinutes())
    let ss = addZero(time.getSeconds())
    return `${YY}-${MM}-${DD} ${hh}:${mm}:${ss}`
}
function timeTextFormat(text) {
    return `${text.slice(0, 10)} ${text.slice(11, 19)}`
}
function sleep(time) {
    let endTime = new Date().getTime() + time
    while(true){
        if (new Date().getTime() > endTime){
            return;
        }
    }
}
function sleepToast(text, second) {
    const {java} = this
    java.log(text)
    java.longToast(text)
    if (second === undefined || second <= 2) {second = 2}
    sleep(1000*second)
}

