    let content = [""]
    // li = "mini thumb small regular original".split(" ")
    let quality = util.settings.QUALITY_REGULAR ? "regular" : "original"
    let illustLink = getAjaxJson(urlIP(urlIllustDetailed(res.id))).body.urls[quality]
